const rows = $input.all();

const avatarOptions = rows
  .filter(r => r.json.idType === 'AVATAR_ID')
  .map(r => `<option value="${r.json.idValue}">${r.json.name}</option>`)
  .join('');

const voiceOptions = rows
  .filter(r => r.json.idType === 'VOICE_CLON_ID')
  .map(r => `<option value="${r.json.idValue}">${r.json.name}</option>`)
  .join('');

// путь submit-вебхука — единственное место, где его правишь в коде
const submitPath = 'gora-03-05-ai-content-video-webform_submit';
// хост берём из запроса, открывшего форму — не привязываемся к домену
const host = $('Get WebForm Webhook').item.json.headers.host;
const submitUrl = `https://${host}/webhook/${submitPath}`;

const html = `<!DOCTYPE html>
<html lang="ru">
<head>
  <meta charset="utf-8">
  <meta name="viewport" content="width=device-width, initial-scale=1">
  <meta name="color-scheme" content="light dark">
  <link rel="stylesheet" href="https://cdn.jsdelivr.net/npm/@picocss/pico@2/css/pico.classless.min.css">
  <title>Генерация Видео</title>
  <style>
    body > main {max-width: 500px;}
    small {margin-bottom: 20px;}
  </style>
</head>
<body>
  <main>
    <h1>Генерация Видео</h1>
    <form id="videoForm" method="POST" action="${submitUrl}">
      <label>Аватар
        <select name="avatarId" required>${avatarOptions}</select>
      </label>
      <label>Голос
        <select name="voiceId" required>${voiceOptions}</select>
      </label>
      <label>Тема для AI или Текст
        <textarea name="text" rows="4"></textarea>
      </label>
      <small class="field-error" data-for="text" style="color: var(--pico-del-color); display: none;">
        Введи тему или текст ролика.
      </small>
      <label>Email
        <input type="email" name="email" required>
      </label>
      <small class="field-error" data-for="email" style="color: var(--pico-del-color); display: none;">
        Укажи корректный email.
      </small>
      <label>
        <input type="checkbox" name="ai" value="1"> AI
      </label>
      <button type="submit" id="submitBtn">Отправить</button>
    </form>

    <article id="successMsg" style="display: none;">
      <h2>Готово!</h2>
      <p>Запрос принят в обработку. Готовый ролик придёт на email.</p>
    </article>
  </main>
  <script>
    const form = document.getElementById('videoForm');
    const successEl = document.getElementById('successMsg');
    const submitBtn = document.getElementById('submitBtn');

    function clearErrors() {
      document.querySelectorAll('.field-error').forEach(el => el.style.display = 'none');
    }
    function showFieldError(name, msg) {
      const el = document.querySelector('.field-error[data-for="' + name + '"]');
      if (el) {
        if (msg) el.textContent = msg;
        el.style.display = 'block';
      }
    }

    form.addEventListener('submit', async (e) => {
      e.preventDefault();
      clearErrors();

      let valid = true;

      // select'ы: на случай пустой базы
      if (!form.avatarId.value) {
        showFieldError('text', 'Нет доступных аватаров в базе.');
        valid = false;
      }
      if (!form.voiceId.value) {
        showFieldError('text', 'Нет доступных голосов в базе.');
        valid = false;
      }

      // текст
      if (!form.text.value.trim()) {
        showFieldError('text', 'Введи текст ролика.');
        valid = false;
      }

      // email: непустой + базовый формат
      const email = form.email.value.trim();
      const at = email.indexOf('@');
      const dot = email.lastIndexOf('.');
      const emailOk = at > 0 && dot > at + 1 && dot < email.length - 1 && !email.includes(' ');
      if (!emailOk) {
        showFieldError('email');
        valid = false;
      }

      if (!valid) return;

      submitBtn.setAttribute('aria-busy', 'true');
      submitBtn.disabled = true;

      try {
        const res = await fetch(form.action, {
          method: 'POST',
          body: new FormData(form),
        });
        if (!res.ok) throw new Error('HTTP ' + res.status);

        form.style.display = 'none';
        successEl.style.display = 'block';
      } catch (err) {
        submitBtn.removeAttribute('aria-busy');
        submitBtn.disabled = false;
        showFieldError('email', 'Ошибка отправки: ' + err.message + '. Попробуйте ещё раз.');
      }
    });
  </script>  
  </body>
</html>`;

return [{ json: { html } }];

const result = {};

for (const item of $input.all()) {
  result[item.json.idValue] = item.json.name;
}

return [{ json: result }];

