const rows = $input.all();
// путь submit-вебхука — единственное место, где его правишь в коде
const submitPath = 'loading-resources-webform_submit';
// хост берём из запроса, открывшего форму — не привязываемся к домену
const host = $('Get WebForm Uploading Resources').item.json.headers.host;
const submitUrl = `https://${host}/webhook/${submitPath}`;

const html = `<!DOCTYPE html>
<html lang="ru">
<head>
  <meta charset="utf-8">
  <meta name="viewport" content="width=device-width, initial-scale=1">
  <meta name="color-scheme" content="light dark">
  <link rel="stylesheet" href="https://cdn.jsdelivr.net/npm/@picocss/pico@2/css/pico.classless.min.css">
  <title>Создать Аватар</title>
  <style>
    body > main {max-width: 500px!important;}
    small { margin-bottom: 20px;}
  </style>  
</head>
<body>
  <main>
    <h1>Создать Аватар</h1>
    <form id="uploadForm" method="POST" action="${submitUrl}" enctype="multipart/form-data">
      <label>Изображение Аватара
        <input type="file" name="avatar" accept="image/*">
      </label>
      <label>Название аватара
        <input type="text" name="avatarName">
      </label>
      <small class="field-error" data-for="avatarName" style="color: var(--pico-del-color); display: none;">
        Укажи название аватара.
      </small>

      <label>Голос Аватара
        <input type="file" name="voice" accept="audio/*">
      </label>
      <label>Название голоса
        <input type="text" name="voiceName">
      </label>
      <small class="field-error" data-for="voiceName" style="color: var(--pico-del-color); display: none;">
        Укажи название голоса.
      </small>
      <label>Описание голоса
        <textarea name="voiceDescription" rows="2" placeholder="Необязательно"></textarea>
      </label>

      <small id="formError" style="color: var(--pico-del-color); display: none;">
        Загрузите хотя бы один файл — фото или голос.
      </small>
      <button type="submit" id="submitBtn">Отправить</button>
    </form>

    <article id="successMsg" style="display: none;">
      <h2>Готово!</h2>
      <p>Файлы отправлены в обработку. Результат придёт в Telegram.</p>
    </article>
  </main>

  <script>
    const form = document.getElementById('uploadForm');
    const formError = document.getElementById('formError');
    const successEl = document.getElementById('successMsg');
    const submitBtn = document.getElementById('submitBtn');

    // прячем все ошибки
    function clearErrors() {
      formError.style.display = 'none';
      document.querySelectorAll('.field-error').forEach(el => el.style.display = 'none');
    }

    // показать ошибку конкретного поля
    function showFieldError(name) {
      const el = document.querySelector('.field-error[data-for="' + name + '"]');
      if (el) el.style.display = 'block';
    }

    form.addEventListener('submit', async (e) => {
      e.preventDefault();
      clearErrors();

      const hasAvatar = form.avatar.files.length > 0;
      const hasVoice = form.voice.files.length > 0;

      // 1. хотя бы один файл
      if (!hasAvatar && !hasVoice) {
        formError.style.display = 'block';
        return;
      }

      let valid = true;

      // 2. avatar выбран -> название обязательно
      if (hasAvatar && !form.avatarName.value.trim()) {
        showFieldError('avatarName');
        valid = false;
      }

      // 3. voice выбран -> название обязательно
      if (hasVoice && !form.voiceName.value.trim()) {
        showFieldError('voiceName');
        valid = false;
      }

      if (!valid) return;

      // 4. description дублируем из названия голоса, только если voice выбран и описание пустое
      if (hasVoice && !form.voiceDescription.value.trim()) {
        form.voiceDescription.value = form.voiceName.value.trim();
      }

      submitBtn.setAttribute('aria-busy', 'true');
      submitBtn.disabled = true;

      try {
        const res = await fetch(form.action, {
          method: 'POST',
          body: new FormData(form),
        });
        if (!res.ok) throw new Error('HTTP ' + res.status);

        form.style.display = 'none';
        successEl.style.display = 'block';
      } catch (err) {
        submitBtn.removeAttribute('aria-busy');
        submitBtn.disabled = false;
        formError.textContent = 'Ошибка отправки: ' + err.message + '. Попробуйте ещё раз.';
        formError.style.display = 'block';
      }
    });
    </script>
  </body>
</html>`;

return [{ json: { html } }];
